-- 불암산 전체 seed data
-- 원본: 산림청 등산로정보 PMNTN / PMNTN_SPOT
-- 산 코드: 113500101(불암산)
-- 원본 건수: PMNTN 135피처, PMNTN_SPOT 152피처
-- 적재 건수: raw_trail 144건, trail_spot 152건
-- 원본 멀티파트 4개는 연결 가능한 조각을 병합한 뒤 LineString 13개로 정규화한다.
-- 원본 좌표계: ITRF2000 TM Korea Central Belt (EPSG:5186 파라미터)
-- DB 저장 좌표계: EPSG:5179
-- 원본 기준일: 2016-12-31, 수집일: 2026-11-23
--
-- 이 파일은 신규 불암산 seed 최초 실행 전용이다.
-- 산·원천 데이터·네트워크·서비스 영역·태그·지점 매칭을 한 트랜잭션으로 처리한다.
-- 기존 관악산 seed와 Flyway migration은 변경하지 않는다.

BEGIN;

-- 같은 이름의 활성 산이 있으면 기존 참조를 보호하기 위해 중단한다.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.mountain
        WHERE mountain_nm = '불암산'
          AND use_yn = 'Y'
    ) THEN
        RAISE EXCEPTION '활성 불암산 데이터가 이미 존재합니다. 이 seed는 최초 실행 전용입니다.';
    END IF;
END
$$;

